import{_ as s,o as t,c as e,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Навыки","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/skills.md","filePath":"ru/guides/skills.md","lastUpdated":1792323081000}'),l={name:"ru/guides/skills.md"};function n(d,a,o,r,p,c){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="навыки" tabindex="-1">Навыки <a class="header-anchor" href="#навыки" aria-label="Permalink to &quot;Навыки&quot;">​</a></h1><p><strong>Навык</strong> (Skill) — это переиспользуемый модуль промпта, который учит Bot фиксированной манере работы: тону, порядку действий, привычкам обращения с инструментами. У навыков нет отдельного экрана управления — навык представляет собой файл в рабочем пространстве, и чтобы он загрузился, достаточно положить его в правильный каталог.</p><div class="tip custom-block"><p class="custom-block-title">Ограничения</p><p>Одна сессия может запросить одновременно не более 5 навыков; один навык внедряет до 64 КиБ, суммарно — до 256 КиБ. Эти лимиты не настраиваются.</p></div><h2 id="как-выглядит-навык" tabindex="-1">Как выглядит навык <a class="header-anchor" href="#как-выглядит-навык" aria-label="Permalink to &quot;Как выглядит навык&quot;">​</a></h2><p>Навык — это каталог, в котором лежит <code>SKILL.md</code> с YAML-заголовком: как минимум стабильное <code>name</code> и короткое <code>description</code>. Тело файла — тот самый текст инструкции, который реально внедряется для агента:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coder-skill</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Enables advanced coding workflows and tool usage.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Coder Skill</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Write clear code, explain trade-offs, and use the file/command tools when the task calls for them.</span></span></code></pre></div><p>Используйте простые ASCII-имена (<code>coder-skill</code>, <code>research</code>) без пробелов — имя одновременно служит именем каталога.</p><h2 id="в-какои-каталог-класть" tabindex="-1">В какой каталог класть <a class="header-anchor" href="#в-какои-каталог-класть" aria-label="Permalink to &quot;В какой каталог класть&quot;">​</a></h2><p>Навыки, которые вы пишете сами, кладите в этот каталог рабочего пространства Bot:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/skills/user/personal/&lt;skill-name&gt;/SKILL.md</span></span></code></pre></div><p>Подойдёт любой способ доставить туда файл: создайте его на вкладке <strong>Files</strong> у Bot, воспользуйтесь <strong>Terminal</strong> или просто попросите самого Bot — в рабочем пространстве уже есть навык <code>skill-creator</code>: опишите нужный порядок действий, и он запишет файлы в правильное место.</p><p>Вы встретите и другие каталоги, но <strong>класть туда файлы вручную не нужно</strong>:</p><table tabindex="0"><thead><tr><th>Каталог</th><th>Кому принадлежит</th></tr></thead><tbody><tr><td><code>/data/skills/user/personal/</code></td><td><strong>Вам.</strong> Все написанные вручную навыки живут здесь</td></tr><tr><td><code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code></td><td><a href="./supermarket.html">Приложениям</a>. Устанавливаются, обновляются и удаляются вместе с приложением — не редактируйте</td></tr><tr><td><code>/data/.memoh/skills/</code></td><td>Встроенные навыки из шаблона рабочего пространства (например, <code>skill-creator</code>). При каждой инициализации рабочего пространства обновляются до версии из шаблона, так что правки будут перезаписаны; для кастомизации скопируйте навык под новым именем в свой каталог</td></tr><tr><td><code>/data/.skills/</code>, <code>/data/.agents/skills/</code></td><td>Устаревшие пути совместимости, только для обнаружения — новые файлы не добавляйте</td></tr></tbody></table><h2 id="несколько-копии-с-одним-именем" tabindex="-1">Несколько копий с одним именем <a class="header-anchor" href="#несколько-копии-с-одним-именем" aria-label="Permalink to &quot;Несколько копий с одним именем&quot;">​</a></h2><p><strong>Имя навыка — это его идентичность</strong>: в скольких бы каталогах ни встречалось одно имя, в каждый момент действует только одна копия. Навык в вашем собственном каталоге имеет приоритет над навыком в устаревшем пути совместимости. Чтобы изменить поведение навыка из приложения, не редактируйте его файлы — напишите собственную версию под новым именем.</p><h2 id="рекомендации" tabindex="-1">Рекомендации <a class="header-anchor" href="#рекомендации" aria-label="Permalink to &quot;Рекомендации&quot;">​</a></h2><ol><li>Пусть навыков будет немного, но метких, с понятными <code>name</code> и <code>description</code> — агент решает, загружать ли навык, по его описанию.</li><li>В навык стоит превращать только повторяющиеся порядки действий; разовые требования можно просто сказать в чате.</li><li>Предпочитайте установку из <a href="./supermarket.html">Supermarket</a> копированию дубликатов.</li></ol>`,17)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
